import csv
import glob

totals = {}
for path in glob.glob("timesheet/*.csv"):
    with open(path, encoding="utf-8", newline="") as f:
        for row in csv.DictReader(f):
            dept = row["姓名"]
            totals[dept] = totals.get(dept, 0) + int(row["工时"])
for dept in sorted(totals):
    print(f"{dept} {totals[dept]} 小时")
